// One viral LinkedIn format: the post that proves it and the template to reuse it.
// The three lists next to this file are generated by scripts/build-viral-formats.py.

export type ViralFormat = {
  id: number;
  name: string;
  why: string;
  picture: string;
  text: string;
  author: string;
  url: string;
  kind: string;
  likes: string;
  comments: string;
  followers: string;
  score: string;
  date: string;
  width: number;
  height: number;
  /** The text of the original post (may be empty: some posts are only a picture). */
  post: string;
  /** The author's LinkedIn headline. */
  headline: string;
  /** File name in /viral-formats/av/, or "" when the author shows no photo. */
  avatar: string;
};
